def main() -> None:
    text = PATH.read_text(encoding="utf-8")
    for old, new in REPLACEMENTS:
        text = text.replace(old, new)
    PATH.write_text(text, encoding="utf-8")
    print("Updated ReadingViewModel.swift")


if __name__ == "__main__":
    main()
